// matchSHA1Table matches the whole of s against the pattern "[0-9a-f]{40}" (types.md, Refinements 11), a walk of tableSHA1.
func matchSHA1Table(s string) bool {
	t := &tableSHA1
	q := 1
	for _, r := range s {
		var c int
		if r < 128 {
			c = int(t.ascii[r])
		} else {
			lo, hi := 0, len(t.hiLo)
			for lo+1 < hi {
				mid := int(uint(lo+hi) >> 1)
				if t.hiLo[mid] <= r {
					lo = mid
				} else {
					hi = mid
				}
			}
			c = int(t.hiCls[lo])
		}
		q = int(t.next[(q-1)*2+c])
		if q == 0 {
			return false
		}
	}
	return t.accept[q-1]
}

